#!/usr/bin/env python3
"""Read the interactive coordinator session's own transcripts: python3 extract_interactive.py <session transcript file> [--until <UTC ISO time>].

The session's subagent transcripts sit in the directory next to the file, named after it. Each probe child is found by what the client
recorded about it: the description of a direct Agent-tool child or teammate (its .meta.json), or the label of a workflow agent (its
workflow's journal.jsonl). Prints, per case, the number of unique assistant message ids and the resolved model and recorded effort
of those messages. The coordinator itself (C7) is counted up to --until, because its transcript keeps growing.
"""
import glob
import json
import os
import sys

from extract_all import summarize

def by_description(root, text):
    for meta in glob.glob(os.path.join(root, "subagents", "agent-*.meta.json")):
        if text in json.load(open(meta)).get("description", ""):
            return meta[: -len(".meta.json")] + ".jsonl"


def by_label(root, label):
    for journal in glob.glob(os.path.join(root, "subagents", "workflows", "*", "journal.jsonl")):
        for line in open(journal):
            row = json.loads(line)
            if row.get("type") == "started" and row.get("label") == label:
                return os.path.join(os.path.dirname(journal), "agent-%s.jsonl" % row["agentId"])


def probe_cases(session):
    """The transcript of each interactive probe case (None when the client kept none), in case order."""
    root = os.path.splitext(session)[0]
    return [
        ("C1", by_description(root, "Probe: unnamed default subagent model")),
        ("C2", by_description(root, "Probe: reviewer frontmatter model")),
        ("C3", by_description(root, "Probe: explicit opus override")),
        ("C4", by_label(root, "inherit-none")),
        ("C5", by_label(root, "alias-sonnet")),
        ("C6", by_description(root, "Probe: named teammate default model")),
        ("C7", session),
        ("C8", by_description(root, "Terminal-Bench 4.0 run path scout")),
    ]


if __name__ == "__main__":
    session = sys.argv[1]
    until = sys.argv[sys.argv.index("--until") + 1] if "--until" in sys.argv else None
    for name, path in probe_cases(session):
        print(name, summarize(path, until if name == "C7" else None) if path else "transcript not found")
